module.exports = function(intervals) {
const mergeIntervals = (intervals) => {
  if (!intervals || intervals.length === 0) {
    return [];
  }

  // 1. Sort the intervals based on the start time (handles unsorted input)
  // We create a copy to avoid mutating the input array.
  const sortedIntervals = [...intervals].sort((a, b) => a[0] - b[0]);

  const merged = [];
  let currentInterval = sortedIntervals[0];

  // 2. Iterate and merge
  for (let i = 1; i < sortedIntervals.length; i++) {
    const nextInterval = sortedIntervals[i];

    // Check for overlap or touching: current end >= next start
    if (currentInterval[1] >= nextInterval[0]) {
      // Merge: update the end time of the current interval
      currentInterval[1] = Math.max(currentInterval[1], nextInterval[1]);
    } else {
      // No overlap: push the current merged interval and start a new one
      merged.push(currentInterval);
      currentInterval = nextInterval;
    }
  }

  // Push the last processed interval
  merged.push(currentInterval);

  return merged;
};

module.exports = mergeIntervals;
};

